import{z as n,x as s,o as r,c as d,q as i,j as l,D as e,d as B,s as o,S as A,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"菲涅尔与夫琅禾费","description":"","frontmatter":{"title":"菲涅尔与夫琅禾费","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fresnel-fraunhofer.md","filePath":"litho/fresnel-fraunhofer.md","lastUpdated":1791063341000}'),p={name:"litho/fresnel-fraunhofer.md"};function F(h,E,m,f,C,D){const t=s("Mermaid");return r(),d("div",null,[E[2]||(E[2]=i('<h1 id="菲涅尔与夫琅禾费" tabindex="-1">菲涅尔与夫琅禾费 <a class="header-anchor" href="#菲涅尔与夫琅禾费" aria-label="Permalink to &quot;菲涅尔与夫琅禾费&quot;">​</a></h1><div class="epigraph"><p>球面子波的相位里藏着观察距离；留下二次项是近场（菲涅尔），只留线性项是远场（夫琅禾费），投影物镜的光瞳平面被故意放在后一种极限里。</p><footer>—— Goodman, Introduction to Fourier Optics 对菲涅尔 / 夫琅禾费衍射的展开</footer></div><p><a href="/litho/kirchhoff-diffraction">上一课</a>把孔径上的边值钉成 Kirchhoff 薄屏，积分核仍是 \\(e^{ikR}/R\\)。缺口是：<strong>\\(R\\) 的哪几阶相位必须保留</strong>。上一课不负责按 \\(z\\) 砍泰勒；本课把近场与远场写成同一积分的两个极限。空间频率如何给这些平面波命名，留给<a href="/litho/diffraction-spatial-freq">衍射与空间频率</a>。仍不要写产线 CD。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 \\(R=\\sqrt{z^2+(x-x&#39;)^2+(y-y&#39;)^2}\\) 让每个观察点都要做一次无法化简的面积分。光刻却经常问两类问题：掩模近处（接近式、泰伯自成像）要不要二次相位；进了投影物镜之后，光瞳上看到的是不是孔径的傅里叶变换。缺口因此是展开判据，而不是再争论铬上该不该写零。</p><p>菲涅尔数 \\(N_F=a^2/(\\lambda z)\\)（\\(a\\) 为孔径特征半径）把「近」和「远」收成无量纲数：\\(N_F\\sim 1\\) 必须留二次项；\\(N_F\\ll 1\\) 才进入夫琅禾费。扫描投影的物–镜距离按几何看并不「无穷远」，但透镜的二次相位抵消了菲涅尔项，光瞳仍落在夫琅禾费域——这是镜头的作用，不是把晶圆搬到千米之外。</p><p><span class="marginnote">数字实例：缝半宽 \\(a=0.5\\) mm、\\(\\lambda=500\\) nm 时，\\(N_F=a^2/(\\lambda z)=0.5/z\\)（\\(z\\) 以米计）。\\(z=0.5\\) m 处 \\(N_F=1\\)，还在近场；退到 \\(z=50\\) m，\\(N_F=0.01\\)，才稳进夫琅禾费区。代入自己那组 \\(a\\)、\\(\\lambda\\) 一算，就不必背「远场要多远」。</span></p><p><span class="marginnote">术语翻译：泰伯（Talbot）效应说的是「周期物体替自己拍立得」——周期为 \\(p\\) 的掩模在菲涅尔区传播 \\(z_T=2p^2/\\lambda\\) 后，光强分布自己重演一遍，\\(2z_T\\)、\\(3z_T\\) 处还会再现。接近式光刻的谐振离焦窗口就蹭了这趟「顺风车」。</span></p><h3 id="二次项与线性项不是两种物理" tabindex="-1">二次项与线性项不是两种物理 <a class="header-anchor" href="#二次项与线性项不是两种物理" aria-label="Permalink to &quot;二次项与线性项不是两种物理&quot;">​</a></h3><p>同一 Kirchhoff 积分，对 \\(R\\) 在光轴附近做二项式展开：常数项给出整体相位，\\(z\\) 分母给出球面振幅，二次项是菲涅尔，把孔径坐标与观察坐标的交叉项再丢掉只剩 \\(\\exp\\bigl[-ik(xx&#39;+yy&#39;)/z\\bigr]\\)，积分变成傅里叶变换，即夫琅禾费。</p><p><span class="marginnote">「远场」在傅里叶光学里指相位的线性化，不自动等于「强度按 \\(1/z^2\\) 的几何远」。光瞳平面上的级次图是夫琅禾费图样；晶圆上的空中像还要再经过一次变换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>菲涅尔近似下（一维示意）</p> \\[U(x,z)\\propto \\frac{e^{ikz}}{z}\\int U(x&#39;,0)\\,\\exp\\Bigl(\\frac{ik}{2z}(x-x&#39;)^2\\Bigr)\\,dx&#39;. \\]<p>这是与二次相位核的卷积，传播可逆，直到倏逝分量被丢掉为止。泰伯距离上周期物会自成像，靠的就是这层二次相位的周期性。接触 / 接近式光刻活在菲涅尔区；投影光刻把物镜插进去，有意离开它。</p><p>夫琅禾费：二次相位在孔径上可视为常数（或被透镜配平），</p> \\[U(x,z)\\propto e^{ikz}\\exp\\Bigl(\\frac{ik x^2}{2z}\\Bigr)\\int U(x&#39;,0)\\,e^{-ik xx&#39;/z}\\,dx&#39;. \\]<p>积分是孔径场的傅里叶变换。Goodman 的透镜傅里叶变换性质把「无穷远」换成后焦面：投影物镜的出瞳坐标与物面空间频率对齐——后课的频率轴从这里开始有几何座位。</p><h3 id="镜头不是把近场「变成」远场的魔法" tabindex="-1">镜头不是把近场「变成」远场的魔法 <a class="header-anchor" href="#镜头不是把近场「变成」远场的魔法" aria-label="Permalink to &quot;镜头不是把近场「变成」远场的魔法&quot;">​</a></h3><p>透镜引入的光程（第一课的 \\(\\int n\\,ds\\)）抵消物方菲涅尔二次相位，使光瞳满足夫琅禾费条件。像方再来一次，晶圆落在物的（被光瞳切过的）像。本课不定义 \\(\\mathrm{NA}\\)；只要求后课说「光瞳是傅里叶面」时，承认已经取了本课的远场极限。</p><p><span class="marginnote">\\(1/z\\) 的振幅随距离掉，干涉条纹的疏密由相位梯度决定。丢掉二次相位却仍在 \\(N_F\\sim 1\\) 的区域算对比，级次位置会整根错。</span></p>',21)),(r(),l(A,null,{default:e(()=>[o(t,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20KIR%5B%22Kirchhoff%20%E7%90%83%E9%9D%A2%E6%A0%B8%22%5D%20--%3E%20EXP%5B%22R%20%E7%9A%84%E4%BA%8C%E9%A1%B9%E5%BC%8F%E5%B1%95%E5%BC%80%22%5D%0A%20%20EXP%20--%3E%20FR%5B%22%E8%8F%B2%E6%B6%85%E5%B0%94%EF%BC%9A%E4%BA%8C%E6%AC%A1%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20EXP%20--%3E%20FF%5B%22%E5%A4%AB%E7%90%85%E7%A6%BE%E8%B4%B9%EF%BC%9A%E5%82%85%E9%87%8C%E5%8F%B6%E5%8F%98%E6%8D%A2%22%5D%0A%20%20FR%20--%3E%20NF%5B%22%E8%BF%91%E5%9C%BA%20%2F%20%E6%B3%B0%E4%BC%AF%22%5D%0A%20%20FF%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%20%3D%20%E5%82%85%E9%87%8C%E5%8F%B6%E9%9D%A2%22%5D%0A%20%20PUP%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%E8%BD%B4%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"近场里，不同面元到观察点的程差还随横向位置二次变化，点物的「像」是菲涅尔衍射斑，不是几何点。远场（或焦面）里，横向结构只通过线性相位——也就是空间频率——进入积分，孔径形状的傅里叶分量直接出现在光瞳上。周期掩模的分立级，正是夫琅禾费核挑出来的那些 \\(\\delta\\) 峰。",-1)),E[5]||(E[5]=a("p",null,"上一课的倾斜因子在两种极限里都还在，只是夫琅禾费常把它并进缓慢变化的振幅，讨论级次位置时先忽略。机制仍是相干叠加，不是「光线在某个距离开始衍射」。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为衍射是从某个距离「开始」的现象，近处没有、远处才有。实际上孔径一打开衍射就在发生，菲涅尔与夫琅禾费只是同一积分在不同保留阶数下的两套近似；选错近似不是衍射消失，而是级次位置和对比度算错。")],-1)),(r(),l(A,null,{default:e(()=>[o(t,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E7%BB%99%E5%AE%9A%E6%8E%A9%E6%A8%A1%E4%B8%8E%E8%A7%82%E5%AF%9F%E8%B7%9D%E7%A6%BB%EF%BC%8C%E7%94%A8%E5%93%AA%E5%A5%97%E8%BF%91%E4%BC%BC%EF%BC%9F%22%5D%20--%3E%20NUM%7B%22%E8%8F%B2%E6%B6%85%E5%B0%94%E6%95%B0%20a%5E2%2F(%CE%BBz)%20%E2%88%BC%201%20%3F%22%7D%0A%20%20NUM%20--%20%22%E6%98%AF%22%20--%3E%20FRES%5B%22%E8%8F%B2%E6%B6%85%E5%B0%94%E5%8C%BA%EF%BC%9A%E4%BF%9D%E7%95%99%E4%BA%8C%E6%AC%A1%E7%9B%B8%E4%BD%8D%EF%BC%8C%E6%8C%89%E5%8D%B7%E7%A7%AF%E7%AE%97%22%5D%0A%20%20FRES%20--%3E%20APP%5B%22%E6%8E%A5%E8%A7%A6%20%2F%20%E6%8E%A5%E8%BF%91%E5%BC%8F%E5%85%89%E5%88%BB%E3%80%81%E6%B3%B0%E4%BC%AF%E8%87%AA%E6%88%90%E5%83%8F%22%5D%0A%20%20NUM%20--%20%22%E5%90%A6%22%20--%3E%20LENS%7B%22%E5%85%89%E8%B7%AF%E9%87%8C%E6%9C%89%E6%B2%A1%E6%9C%89%E9%80%8F%E9%95%9C%EF%BC%9F%22%7D%0A%20%20LENS%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20FF%5B%22%E5%A4%AB%E7%90%85%E7%A6%BE%E8%B4%B9%E5%8C%BA%EF%BC%9A%E7%9B%B4%E6%8E%A5%E4%BD%9C%E5%82%85%E9%87%8C%E5%8F%B6%E5%8F%98%E6%8D%A2%22%5D%0A%20%20LENS%20--%20%22%E6%9C%89%22%20--%3E%20LFFT%5B%22%E9%80%8F%E9%95%9C%E6%8A%B5%E6%B6%88%E4%BA%8C%E6%AC%A1%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20FF%20--%3E%20PUP%5B%22%E5%AD%94%E5%BE%84%E7%9A%84%E5%82%85%E9%87%8C%E5%8F%B6%E5%88%86%E9%87%8F%E5%87%BA%E7%8E%B0%E5%9C%A8%E8%A7%82%E5%AF%9F%E9%9D%A2%E4%B8%8A%22%5D%0A%20%20LFFT%20--%3E%20PUP%0A%20%20PUP%20--%3E%20NEXT%5B%22%E5%85%89%E7%9E%B3%E5%8D%B3%E5%82%85%E9%87%8C%E5%8F%B6%E9%9D%A2%20%E2%86%92%20%E5%90%8E%E8%AF%BE%E7%9A%84%E7%A9%BA%E9%97%B4%E9%A2%91%E7%8E%87%E8%BD%B4%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到投影成像的物–瞳关系，默认夫琅禾费 / 透镜傅里叶变换；说到接近式或层间近场串扰，默认菲涅尔。角谱是同一传播的平面波基底，下一课给它装上 \\(f_x=n\\sin\\theta/\\lambda\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>展开假定傍轴或至少 \\(z\\) 大于横向尺度；高 \\(\\mathrm{NA}\\) 边缘光线的 \\(R\\) 展开要留更高阶，后课矢量成像再管偏振，本课不把 \\(\\mathrm{NA}\\) 写进判据。也不要把夫琅禾费理解成「必须真空传播很远」：透镜可以就地制造傅里叶面。本课不引用未公开的物镜焦面公差。</p><p>有限带宽让每个 \\(\\lambda\\) 的菲涅尔数不同，那是色差课的微扰，此处仍单色。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kirchhoff 核已给定；本课按 \\(z\\) 决定留二次项还是只留傅里叶核。</li><li>菲涅尔数 \\(a^2/(\\lambda z)\\) 判断近场；透镜把光瞳放到夫琅禾费域。</li><li>近场是卷积，远场是孔径的傅里叶变换。</li><li>后课的空间频率轴坐在夫琅禾费光瞳上。</li><li>本课不定义 \\(\\mathrm{NA}\\)，不写瑞利 CD。</li><li>出处：Goodman, <em>Introduction to Fourier Optics</em>。</li></ul>',7))])}const x=n(p,[["render",F]]);export{c as __pageData,x as default};
